    body=bd.Pos(0,0,params['thickness']/2)*bd.Box(35,10,params['thickness'])
    hook=bd.Plane.XZ*bd.Polygon((12,0),(17.5,0),(17.5,params['thickness']+3),(12,params['thickness']),align=None)
